static <T> T firstSuccessful(List<Callable<T>> tasks, ExecutorService pool) throws Exception {
    List<Future<T>> futures = new ArrayList<>();
    for (Callable<T> t : tasks) futures.add(pool.submit(t));
    while (true) {
        for (Future<T> f : futures) if (f.isDone() && !f.isCancelled()) { T wynik = f.get(); for (Future<T> other : futures) if (other != f) other.cancel(true); return wynik; }
        Thread.sleep(5);
    }
}
