Semaphore semaphore = new Semaphore(2);
ExecutorService pool = Executors.newFixedThreadPool(8);
List<Future<Integer>> futures = new ArrayList<>();
for (int i=1;i<=8;i++) { int id=i; futures.add(pool.submit(() -> { semaphore.acquire(); try { Thread.sleep(50); return id*id; } finally { semaphore.release(); } })); }
int zebrane = 0; for (Future<Integer> f : futures) { f.get(); zebrane++; }
System.out.println(zebrane == 8);
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

int[] dane = new Random().ints(1000, 0, 10000).toArray();
ExecutorService pool = Executors.newFixedThreadPool(4);
List<Future<Integer>> futures = new ArrayList<>();
int chunk = 250;
for (int i=0;i<4;i++) { int start=i*chunk, end=(i+1)*chunk; futures.add(pool.submit(() -> { int max=Integer.MIN_VALUE; for (int j=start;j<end;j++) max=Math.max(max, dane[j]); return max; })); }
int maxOgolny = Integer.MIN_VALUE; for (Future<Integer> f : futures) maxOgolny = Math.max(maxOgolny, f.get());
int oczekiwany = Arrays.stream(dane).max().getAsInt();
System.out.println(maxOgolny == oczekiwany);
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

