record OrderResult(int orderId, double price, String error) {}
ExecutorService pool = Executors.newFixedThreadPool(4);
Set<Integer> bledne = Set.of(4,8);
List<Future<OrderResult>> futures = new ArrayList<>();
for (int i=1;i<=10;i++) { int id=i; futures.add(pool.submit(() -> { if (bledne.contains(id)) throw new RuntimeException("blad zamowienia "+id); return new OrderResult(id, id*9.99, null); })); }
double przychod = 0; List<Integer> nieudane = new ArrayList<>();
for (int i=0;i<futures.size();i++) { try { przychod += futures.get(i).get().price(); } catch (ExecutionException e) { nieudane.add(i+1); } }
System.out.println("przychod="+przychod+" nieudane="+nieudane);
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);
